def find_max(items):        # O(n) — one pass
    best = items[0]
    for x in items[1:]:
        if x > best:
            best = x
    return best

def has_duplicates(items):   # O(n^2) naive, O(n) with a set
    return len(items) != len(set(items))

def binary_search(a, target):  # O(log n)
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
